function flatten(value) {
  const result = [];

  function recurse(arr) {
    for (const item of arr) {
      if (Array.isArray(item)) {
        recurse(item);
      } else {
        result.push(item);
      }
    }
  }

  if (Array.isArray(value)) {
    recurse(value);
  }

  return result;
}
